insert into public.authors (slug, name, period, years, place, bio, works, hue, featured, sort, status) values ('mast-tawakali', '{"bal":"مست توکلی","bal-latn":"Mast Tawakali","en":"Mast Tawakali","ur":"مست توکلی"}'::jsonb, 'classical', '1825–1892', '{"bal":"کوہستانِ مری","bal-latn":"Kóhestán-e Marri","en":"Marri hills","ur":"مری کوہستان"}'::jsonb, '{"bal":"بلوچی کلاسیکی شاعری ءِ مزنیں نام، عشق ءُ تصوف ءِ شاعر.","bal-latn":"Balòchi kelásiki shá''eri é mazanén nám, eshk o tasawwuf é shá''er.","en":"A towering name of classical Balochi poetry — a poet of love and Sufi devotion.","ur":"بلوچی کلاسیکی شاعری کا بڑا نام — عشق اور تصوف کے شاعر۔"}'::jsonb, 64, 32, false, 0, 'published');
insert into public.authors (slug, name, period, years, place, bio, works, hue, featured, sort, status) values ('jam-durrak', '{"bal":"جام دُرّک","bal-latn":"Jám Durrak","en":"Jam Durrak","ur":"جام درک"}'::jsonb, 'classical', '18th c.', '{"bal":"کلات","bal-latn":"Kalát","en":"Kalat","ur":"قلات"}'::jsonb, '{"bal":"کلات ءِ دربار ءِ شاعر، بلوچی غزل ءِ پیش رو.","bal-latn":"Kalát é darbár é shá''er, Balòchi ghazal é pésh-rav.","en":"Court poet of Kalat, remembered as a pioneer of the Balochi lyric.","ur":"دربارِ قلات کے شاعر، بلوچی غزل کے پیش رو۔"}'::jsonb, 41, 18, false, 1, 'published');
insert into public.authors (slug, name, period, years, place, bio, works, hue, featured, sort, status) values ('gul-khan-naseer', '{"bal":"گل خان نصیر","bal-latn":"Gul Khán Nasír","en":"Gul Khan Naseer","ur":"گل خان نصیر"}'::jsonb, 'modern', '1914–1983', '{"bal":"نوشکی","bal-latn":"Nóshki","en":"Noshki","ur":"نوشکی"}'::jsonb, '{"bal":"ملک الشعرا — نوکیں بلوچی شاعری ءِ بنیاد کنوک.","bal-latn":"Malek-ul-Sho''ará — nókén Balòchi shá''eri é buniád kanók.","en":"Honoured as Malik-ush-Shu''ara, a founding voice of modern Balochi poetry.","ur":"ملک الشعرا — جدید بلوچی شاعری کی بنیادی آواز۔"}'::jsonb, 112, 42, true, 2, 'published');
insert into public.authors (slug, name, period, years, place, bio, works, hue, featured, sort, status) values ('atta-shad', '{"bal":"عطا شاد","bal-latn":"Atá Shád","en":"Atta Shad","ur":"عطا شاد"}'::jsonb, 'modern', '1939–1997', '{"bal":"کیچ","bal-latn":"Kéch","en":"Kech","ur":"کیچ"}'::jsonb, '{"bal":"نوکیں بلوچی شعر ءِ ماڈرنسٹ شاعر.","bal-latn":"Nókén Balòchi shé''r é modernist shá''er.","en":"The modernist who reshaped the form and imagery of Balochi verse.","ur":"جدید بلوچی نظم کو نئی ہیئت اور نئے استعارے دینے والے شاعر۔"}'::jsonb, 87, 8, false, 3, 'published');
insert into public.authors (slug, name, period, years, place, bio, works, hue, featured, sort, status) values ('zahoor-shah-hashmi', '{"bal":"سید ظہور شاہ ہاشمی","bal-latn":"Sayad Zahúr Sháh Háshmi","en":"Syed Zahoor Shah Hashmi","ur":"سید ظہور شاہ ہاشمی"}'::jsonb, 'modern', '1926–1978', '{"bal":"گوادر","bal-latn":"Gwádar","en":"Gwadar","ur":"گوادر"}'::jsonb, '{"bal":"شاعر ءُ لبزبلد ءِ نبشتہ کار — سید گنج ءِ مستر.","bal-latn":"Shá''er o labzbald é nebeshtakár — Sayad Ganj é mastar.","en":"Poet and lexicographer, author of the Balochi dictionary Sayad Ganj.","ur":"شاعر اور لغت نویس — بلوچی لغت ''سید گنج'' کے مصنف۔"}'::jsonb, 59, 50, false, 4, 'published');
