insert into public.folk_items (title, body, glyph, sort, status) values ('{"bal":"شیر","bal-latn":"Shér","en":"Shér — the epic ballad","ur":"شیر — رزمیہ داستان"}'::jsonb, '{"bal":"رند ءُ لاشار ءِ جنگ ءُ میر چاکر ءِ داستان.","bal-latn":"Rend o Láshár é jang o Mir Chákar é dástán.","en":"Heroic narrative verse — the Rind–Lashari wars and the saga of Mir Chakar.","ur":"رزمیہ منظوم داستانیں — رند و لاشار کی جنگیں اور میر چاکر کی کہانی۔"}'::jsonb, '◆', 0, 'published');
insert into public.folk_items (title, body, glyph, sort, status) values ('{"bal":"زہیروک","bal-latn":"Zahirók","en":"Zahirok — the song of longing","ur":"زہیروک — ہجر کا گیت"}'::jsonb, '{"bal":"دوری ءُ یات ءِ گیت، کہ زالبولانی توار ءَ زندگ اِنت.","bal-latn":"Dóri o yát é git, ke zálbólání tawárá zendag ent.","en":"Melodies of separation and remembrance, kept alive largely by women''s voices.","ur":"جدائی اور یاد کے گیت، جو زیادہ تر خواتین کی آواز میں زندہ ہیں۔"}'::jsonb, '✦', 1, 'published');
