insert into public.hero_slides (heading, description, cta, sort) values ('{"bal":"بلوچی شاعری ءِ گنج","bal-latn":"Balòchi shá''eri é ganj","en":"The treasury of Balochi poetry","ur":"بلوچی شاعری کا خزانہ"}'::jsonb, '{"bal":"کوہنیں ءُ نوکیں شعر، اصل بلوچی ءَ — رومن ءُ رجانک ءِ همراہ.","bal-latn":"Kóhnén o nókén shé''r, asl Balòchi á — Roman o rajánk é hamráh.","en":"Classical and modern verse in the original Balochi, with Roman script and translations.","ur":"کلاسیکی اور جدید شاعری اصل بلوچی میں — رومن اور ترجمے کے ساتھ۔"}'::jsonb, '[{"label":{"bal":"شعر بوانیں","bal-latn":"Shé''r bewánén","en":"Read poetry","ur":"شاعری پڑھیں"},"href":"@poetry"}]'::jsonb, 0);
